<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
type Event={id:number;actor_name:string;from_status:string;to_status:string;note:string;created_at:string}
type Appointment={station_id:number;scheduled_at:string;code_expires_at:string;failed_attempts:number;verified_at:string|null;claimant_confirmed_at:string|null;staff_confirmed_at:string|null}
type Claim={id:string;found_item_id:string;item_title:string;related_lost_item_id:string|null;statement:string;evidence:Record<string,unknown>;status:string;decision_note:string;submitted_at:string;decided_at:string;events:Event[];appointment?:Appointment;allowed_actions:string[]}
type Station={id:number;name:string}
const route=useRoute();const claim=ref<Claim|null>(null);const stations=ref<Station[]>([]);const loading=ref(true);const busy=ref(false);const error=ref('');const success=ref('')
const decision=reactive({decision:'APPROVE',note:''});const appointment=reactive({station_id:'',scheduled_at:''});const oneTimeCode=ref('')
const canDecide=computed(()=>claim.value?.allowed_actions.includes('decide'));const canSchedule=computed(()=>claim.value?.allowed_actions.includes('schedule_handover')&&!claim.value?.appointment)
async function load(){try{const [claimResponse,stationResponse]=await Promise.all([api<{data:Claim}>(`/claims/${route.params.id}/`),api<{data:{items:Station[]}}>('/stations/?page_size=100')]);claim.value=claimResponse.data;stations.value=stationResponse.data.items;appointment.station_id=String(stations.value[0]?.id??'')}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取认领详情'}finally{loading.value=false}}
async function decide(){if(!claim.value)return;busy.value=true;error.value='';try{await api(`/claims/${claim.value.id}/decision/`,{method:'POST',body:JSON.stringify(decision)});success.value='审核决定已记录';await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'操作失败'}finally{busy.value=false}}
async function schedule(){if(!claim.value)return;busy.value=true;error.value='';try{const response=await api<{data:{one_time_code:string}}>(`/claims/${claim.value.id}/appointment/`,{method:'POST',body:JSON.stringify({station_id:appointment.station_id,scheduled_at:new Date(appointment.scheduled_at).toISOString()})});oneTimeCode.value=response.data.one_time_code;success.value='预约已创建；交接码仅本次显示';await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'预约失败'}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page detail"><p v-if="loading" class="empty">正在读取不可篡改流程记录…</p><p v-else-if="error&&!claim" class="empty error">{{error}}</p><template v-else-if="claim"><header><div><p class="eyebrow">P17 · CLAIM {{claim.id.slice(0,8)}}</p><h1 class="page-title">{{claim.item_title}}</h1><p class="page-lead">{{claim.statement}}</p></div><span class="status-large">{{claim.status}}</span></header><p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p><section class="detail-grid"><div class="panel timeline"><p class="eyebrow">AUDITABLE TIMELINE</p><h2>处理时间线</h2><ol><li v-for="entry in claim.events" :key="entry.id"><i></i><div><strong>{{entry.to_status}}</strong><span>{{entry.actor_name||'系统'}} · {{new Date(entry.created_at).toLocaleString('zh-CN')}}</span><p>{{entry.note||'无备注'}}</p></div></li></ol><div v-if="!claim.events.length" class="muted">尚无事件记录。</div></div><aside><section class="panel summary"><p class="eyebrow">PRIVATE EVIDENCE</p><h2>举证摘要</h2><pre>{{JSON.stringify(claim.evidence,null,2)}}</pre><p v-if="claim.decision_note">决定备注：{{claim.decision_note}}</p><RouterLink :to="`/items/${claim.found_item_id}`">查看对应招领信息</RouterLink></section><form v-if="canDecide" class="panel action" @submit.prevent="decide"><h2>协调员审核</h2><select v-model="decision.decision"><option value="APPROVE">批准并唯一保留</option><option value="NEEDS_INFO">要求补充</option><option value="REJECT">驳回</option></select><textarea v-model="decision.note" required placeholder="记录决定依据"></textarea><button class="button button-brand" :disabled="busy">提交决定</button></form><form v-if="canSchedule" class="panel action" @submit.prevent="schedule"><h2>预约交接</h2><select v-model="appointment.station_id"><option v-for="station in stations" :key="station.id" :value="station.id">{{station.name}}</option></select><input v-model="appointment.scheduled_at" required type="datetime-local"/><button class="button button-brand" :disabled="busy">生成一次性交接码</button></form><section v-if="oneTimeCode" class="code"><span>仅本次显示</span><strong>{{oneTimeCode}}</strong><p>请勿通过公开页面传播。</p></section><RouterLink v-if="claim.status==='HANDOVER_PENDING'" class="button button-ghost handover" :to="`/handover/${claim.id}`">进入安全交接 <AppIcon name="arrow"/></RouterLink></aside></section></template></div></template>
<style scoped>.detail header{display:flex;justify-content:space-between;align-items:end;gap:25px}.status-large{padding:14px 20px;color:var(--ct-brand);border:1px solid var(--ct-border-strong);border-radius:13px}.notice{padding:12px;border-radius:10px}.notice.error{color:var(--ct-danger);background:rgba(255,111,120,.07)}.notice.success{color:var(--ct-success);background:rgba(82,211,154,.07)}.detail-grid{display:grid;grid-template-columns:1fr 370px;gap:18px;margin-top:34px}.timeline,.summary,.action{padding:25px;box-shadow:none}.timeline h2,.summary h2{margin:10px 0 24px}.timeline ol{margin:0;padding:0;list-style:none}.timeline li{display:grid;grid-template-columns:20px 1fr;gap:12px;min-height:100px}.timeline i{position:relative;width:10px;height:10px;margin-top:5px;border-radius:50%;background:var(--ct-brand);box-shadow:0 0 12px var(--ct-brand)}.timeline i:after{position:absolute;top:15px;bottom:-80px;left:4px;width:1px;background:var(--ct-border);content:''}.timeline li:last-child i:after{display:none}.timeline span{display:block;margin-top:5px;color:var(--ct-text-muted);font-size:11px}.timeline p{color:var(--ct-text-muted)}aside{display:grid;align-content:start;gap:12px}.summary pre{overflow:auto;padding:13px;color:var(--ct-info);background:var(--ct-bg);border-radius:10px}.summary>p{color:var(--ct-text-muted)}.summary>a{color:var(--ct-brand)}.action{display:grid;gap:12px}.action h2{margin:0 0 6px}.action select,.action textarea,.action input{width:100%;padding:12px;color:var(--ct-text);border:1px solid var(--ct-border);border-radius:10px;background:var(--ct-bg-soft)}.action textarea{min-height:90px}.code{padding:18px;color:var(--ct-brand);border:1px solid var(--ct-border-strong);border-radius:14px;background:rgba(245,185,66,.06);text-align:center}.code span,.code p{display:block;color:var(--ct-text-muted);font-size:11px}.code strong{display:block;margin:8px;font:800 30px monospace;letter-spacing:.2em}.handover{justify-content:center}.empty{display:grid;place-items:center;min-height:320px}.error{color:var(--ct-danger)}@media(max-width:850px){.detail-grid{grid-template-columns:1fr}.detail header{align-items:start;flex-direction:column}}</style>
